        static Texture2D Rounded(Color color){var t=new Texture2D(32,32,TextureFormat.RGBA32,false);t.wrapMode=TextureWrapMode.Clamp;for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Max(8-x,x-23),dy=Mathf.Max(8-y,y-23);float distance=Mathf.Sqrt(Mathf.Max(0,dx)*Mathf.Max(0,dx)+Mathf.Max(0,dy)*Mathf.Max(0,dy));Color c=color;c.a*=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(7,8,distance));t.SetPixel(x,y,c);}t.Apply();return t;}
