            if(!compact)GUI.Label(new Rect(420,by+8,Mathf.Max(50,width-450),22),App.Status,small);
            Box(metrics);if(GUI.Button(new Rect(metrics.x+8,metrics.y+5,metrics.width-16,26),App.FPS.ToString("F0")+" FPS   ·   "+App.ActiveCount+" / 4 casts   ·   "+(ShowMetrics?"Close":"Metrics"),button))ShowMetrics=!ShowMetrics;
            if(ShowMetrics){GUI.Label(new Rect(metrics.x+14,metrics.y+43,270,76),"CPU update: "+App.CpuMilliseconds.ToString("F2")+" ms\nResolution: "+Screen.width+" × "+Screen.height+"\nRender scale: "+App.ResolutionScale.ToString("P0")+"\nGPU: "+SystemInfo.graphicsDeviceName,label);if(GUI.Button(new Rect(metrics.x+12,metrics.y+125,128,30),"Balanced",button))App.SetQuality(false);if(GUI.Button(new Rect(metrics.x+151,metrics.y+125,128,30),"Economy",button))App.SetQuality(true);GUI.Label(new Rect(metrics.x+12,metrics.y+163,270,20),"Graphics preferences are saved on this device.",small);}
