        void Slider(string key,string name,float min,float max){if(filter.Length>0&&name.IndexOf(filter,StringComparison.OrdinalIgnoreCase)<0&&key.IndexOf(filter,StringComparison.OrdinalIgnoreCase)<0)return;float value=App.Settings.F(key);GUILayout.BeginHorizontal();GUILayout.Label(name,small);GUILayout.FlexibleSpace();GUILayout.Label(value.ToString("0.##"),small,GUILayout.Width(45));GUILayout.EndHorizontal();float next=GUILayout.HorizontalSlider(value,min,max);if(Mathf.Abs(next-value)>.00001f)App.Settings.Set(key,next);}
